def library_catalog() -> list[dict]:
    """Structured, hand-authored and deduplicated library records."""
    result = []
    for name, area, description, docs, package, raw in LIBRARY_ROWS:
        members = []
        for entry in raw.split(";"):
            label, explanation = entry.split("~", 1)
            members.append({"name": label, "description": explanation})
        # Every example is specific to its library; never silently reuse generic demo.
        assert name in EXAMPLE_CODE, f"Missing curated example for {name}"
        result.append({
            "id": name.casefold().replace(" ", "-"),
            "name": name, "area": area, "description": description,
            "documentation_url": docs, "pip_install": f"pip install {package}",
            "members": members, "code_example": EXAMPLE_CODE[name],
            "source": "Documentación oficial enlazada", "language": "Python",
        })
    assert len({x["id"] for x in result}) == len(result)
    return result

